import fastify from './fastify.js'

const app = fastify()
const handler = async () => 'ok'

try {
  app.route({ method: 'GET', url: '/proxy/*', handler })
  app.route({
    method: ['POST', 'DELETE', 'PUT', 'HEAD', 'OPTIONS'],
    url: '/proxy/*',
    handler
  })
  await app.ready()
} catch (err) {
  if (/Method 'HEAD' already declared/.test(String(err && err.message))) {
    console.log('WHOBROKEIT_BUG: expected routes GET + [POST, DELETE, PUT, HEAD, OPTIONS] on the same url to register fine, but got: ' + err.message)
    process.exitCode = 1
  } else {
    throw err
  }
}

if (!process.exitCode) {
  await app.close()
  process.exitCode = 0
}
